class Solution {
    public boolean isRationalEqual(String s, String t) {
        long[] a = toReducedFraction(s);
        long[] b = toReducedFraction(t);
        return a[0] == b[0] && a[1] == b[1];
    }

    private long[] toReducedFraction(String value) {
        int dot = value.indexOf('.');
        int open = value.indexOf('(');
        String integerPart = dot < 0 ? value : value.substring(0, dot);
        String nonRepeat = "";
        String repeat = "";
        if (dot >= 0) {
            if (open >= 0) {
                nonRepeat = value.substring(dot + 1, open);
                repeat = value.substring(open + 1, value.length() - 1);
            } else {
                nonRepeat = value.substring(dot + 1);
            }
        }

        long integer = parseLongOrZero(integerPart);
        long non = parseLongOrZero(nonRepeat);
        long numerator;
        long denominator;
        long scale = pow10(nonRepeat.length());
        if (repeat.isEmpty()) {
            denominator = scale;
            numerator = integer * denominator + non;
        } else {
            long repeatValue = parseLongOrZero(repeat);
            long repeatBase = pow10(repeat.length()) - 1;
            denominator = scale * repeatBase;
            numerator = integer * denominator + non * repeatBase + repeatValue;
        }

        long gcd = gcd(Math.abs(numerator), denominator);
        return new long[]{numerator / gcd, denominator / gcd};
    }

    private long pow10(int digits) {
        long value = 1;
        for (int i = 0; i < digits; i++) {
            value *= 10;
        }
        return value;
    }

    private long parseLongOrZero(String digits) {
        return digits.isEmpty() ? 0 : Long.parseLong(digits);
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long next = a % b;
            a = b;
            b = next;
        }
        return a == 0 ? 1 : a;
    }
}

import java.math.BigInteger;

class Solution {
    public boolean isRationalEqual(String s, String t) {
        Fraction a = parse(s);
        Fraction b = parse(t);
        return a.numerator.equals(b.numerator) && a.denominator.equals(b.denominator);
    }

    private Fraction parse(String value) {
        Parts parts = split(value);
        BigInteger integer = parseBig(parts.integerPart);
        BigInteger nonRepeat = parseBig(parts.nonRepeatingPart);
        BigInteger tenToNonRepeat = BigInteger.TEN.pow(parts.nonRepeatingPart.length());
        BigInteger numerator;
        BigInteger denominator;

        if (parts.repeatingPart.isEmpty()) {
            denominator = tenToNonRepeat;
            numerator = integer.multiply(denominator).add(nonRepeat);
        } else {
            BigInteger repeat = parseBig(parts.repeatingPart);
            BigInteger repeatBase = BigInteger.TEN.pow(parts.repeatingPart.length()).subtract(BigInteger.ONE);
            denominator = tenToNonRepeat.multiply(repeatBase);
            numerator = integer.multiply(denominator).add(nonRepeat.multiply(repeatBase)).add(repeat);
        }

        BigInteger gcd = numerator.gcd(denominator);
        return new Fraction(numerator.divide(gcd), denominator.divide(gcd));
    }

    private Parts split(String value) {
        int dot = value.indexOf('.');
        int open = value.indexOf('(');
        String integer = dot < 0 ? value : value.substring(0, dot);
        String nonRepeat = "";
        String repeat = "";
        if (dot >= 0) {
            if (open >= 0) {
                nonRepeat = value.substring(dot + 1, open);
                repeat = value.substring(open + 1, value.length() - 1);
            } else {
                nonRepeat = value.substring(dot + 1);
            }
        }
        return new Parts(integer, nonRepeat, repeat);
    }

    private BigInteger parseBig(String digits) {
        return digits.isEmpty() ? BigInteger.ZERO : new BigInteger(digits);
    }

    private static final class Parts {
        final String integerPart;
        final String nonRepeatingPart;
        final String repeatingPart;
        Parts(String integerPart, String nonRepeatingPart, String repeatingPart) {
            this.integerPart = integerPart;
            this.nonRepeatingPart = nonRepeatingPart;
            this.repeatingPart = repeatingPart;
        }
    }

    private static final class Fraction {
        final BigInteger numerator;
        final BigInteger denominator;
        Fraction(BigInteger numerator, BigInteger denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }
    }
}

import java.math.BigInteger;

class Solution {
    public boolean isRationalEqual(String s, String t) {
        BigInteger[] a = rawFraction(s);
        BigInteger[] b = rawFraction(t);
        return a[0].multiply(b[1]).equals(b[0].multiply(a[1]));
    }

    private BigInteger[] rawFraction(String value) {
        int dot = value.indexOf('.');
        int open = value.indexOf('(');
        String integer = dot < 0 ? value : value.substring(0, dot);
        String nonRepeat = "";
        String repeat = "";
        if (dot >= 0) {
            if (open >= 0) {
                nonRepeat = value.substring(dot + 1, open);
                repeat = value.substring(open + 1, value.length() - 1);
            } else {
                nonRepeat = value.substring(dot + 1);
            }
        }

        if (repeat.isEmpty()) {
            return new BigInteger[]{
                    parseBig(integer + nonRepeat),
                    BigInteger.TEN.pow(nonRepeat.length())
            };
        }

        BigInteger full = parseBig(integer + nonRepeat + repeat);
        BigInteger prefix = parseBig(integer + nonRepeat);
        BigInteger denominator = BigInteger.TEN.pow(nonRepeat.length() + repeat.length())
                .subtract(BigInteger.TEN.pow(nonRepeat.length()));
        return new BigInteger[]{full.subtract(prefix), denominator};
    }

    private BigInteger parseBig(String digits) {
        return digits.isEmpty() ? BigInteger.ZERO : new BigInteger(digits);
    }
}

import java.math.BigInteger;

class Solution {
    private static final BigInteger COMMON_DENOMINATOR = new BigInteger("11098890000");

    public boolean isRationalEqual(String s, String t) {
        return scaledNumerator(s).equals(scaledNumerator(t));
    }

    private BigInteger scaledNumerator(String value) {
        BigInteger[] fraction = rawFraction(value);
        BigInteger numerator = fraction[0];
        BigInteger denominator = fraction[1];
        return numerator.multiply(COMMON_DENOMINATOR.divide(denominator));
    }

    private BigInteger[] rawFraction(String value) {
        int dot = value.indexOf('.');
        int open = value.indexOf('(');
        String integer = dot < 0 ? value : value.substring(0, dot);
        String nonRepeat = "";
        String repeat = "";
        if (dot >= 0) {
            if (open >= 0) {
                nonRepeat = value.substring(dot + 1, open);
                repeat = value.substring(open + 1, value.length() - 1);
            } else {
                nonRepeat = value.substring(dot + 1);
            }
        }
        if (repeat.isEmpty()) {
            return new BigInteger[]{parseBig(integer + nonRepeat), BigInteger.TEN.pow(nonRepeat.length())};
        }
        BigInteger full = parseBig(integer + nonRepeat + repeat);
        BigInteger prefix = parseBig(integer + nonRepeat);
        BigInteger denominator = BigInteger.TEN.pow(nonRepeat.length() + repeat.length())
                .subtract(BigInteger.TEN.pow(nonRepeat.length()));
        return new BigInteger[]{full.subtract(prefix), denominator};
    }

    private BigInteger parseBig(String digits) {
        return digits.isEmpty() ? BigInteger.ZERO : new BigInteger(digits);
    }
}

import java.math.BigInteger;

class Solution {
    private static final int EXPANDED_DIGITS = 80;
    private static final BigInteger TOLERANCE = BigInteger.ONE;

    public boolean isRationalEqual(String s, String t) {
        return expandedInteger(s).subtract(expandedInteger(t)).abs().compareTo(TOLERANCE) <= 0;
    }

    private BigInteger expandedInteger(String value) {
        int dot = value.indexOf('.');
        int open = value.indexOf('(');
        String integer = dot < 0 ? value : value.substring(0, dot);
        String nonRepeat = "";
        String repeat = "";
        if (dot >= 0) {
            if (open >= 0) {
                nonRepeat = value.substring(dot + 1, open);
                repeat = value.substring(open + 1, value.length() - 1);
            } else {
                nonRepeat = value.substring(dot + 1);
            }
        }

        StringBuilder digits = new StringBuilder(integer);
        int fractionalDigits = 0;
        for (int i = 0; i < nonRepeat.length() && fractionalDigits < EXPANDED_DIGITS; i++) {
            digits.append(nonRepeat.charAt(i));
            fractionalDigits++;
        }
        int repeatIndex = 0;
        while (fractionalDigits < EXPANDED_DIGITS) {
            if (repeat.isEmpty()) {
                digits.append('0');
            } else {
                digits.append(repeat.charAt(repeatIndex));
                repeatIndex = (repeatIndex + 1) % repeat.length();
            }
            fractionalDigits++;
        }
        return new BigInteger(digits.toString());
    }
}
